import re
"""Generate a bilingual, crawlable static portfolio. Run with Python 3."""
from pathlib import Path
import json, re, html, shutil, os
from portfolio_extras import evidence, review_page, testimonials, footer_controls, portfolio_evidence, esdf_optimized_evidence

ROOT=Path(__file__).parent
E=lambda s:html.escape(str(s),quote=True)
projects=json.loads((ROOT/'portfolio-data.json').read_text(encoding='utf-8'))
projects=[p for p in projects if not p['hidden']]
names={'Islamnashaat Translation Toolkit':'Translation Toolkit','alphafood-machine':'Alpha Food Machinery','miss natural Store':'Miss Natural','blackfox':'Blackfox','muhak store':'Muhak Store','mulzam law firm':'Mulzam Law Firm','thefitnest':'The Fitnest','tatweej':'Tatweej','cis-sud':'CIS Sudan','elias':'Dr. Elias Filimban','enjaz-lines-net':'Enjaz Lines','goolden-knights':'Golden Knights','ESDF-eg':'ESDF Egypt'}
for p in projects:
    p['name']=names.get(p['name'],p['name'])
    p['slug']=re.sub('[^a-z0-9]+','-',p['name'].lower()).strip('-')
    p['tags']=[t for t in p['tags'] if 'Optimization' not in t and t not in ['Custom Theme','Responsive Development','Responsive Design']]
    p['tags']=[{'wordpress':'WordPress','elementor':'Elementor','wooCommerce':'WooCommerce','salla':'Salla'}.get(t,t) for t in p['tags']]
    p['ar']=p['name']

