    for n,(a,b,c,d) in enumerate([('WordPress','ووردبريس','Websites, plugins, and flexible solutions for real business needs.','مواقع وإضافات وحلول مرنة تناسب احتياجات العمل.'),('Ecommerce','التجارة الإلكترونية','WooCommerce and Salla stores with practical shopping experiences.','متاجر ووكومرس وسلة بتجارب تسوّق عملية.'),('Frontend','الواجهات الأمامية','Precise, responsive interfaces from your approved design.','واجهات دقيقة ومتجاوبة من تصميمك المعتمد.')],1):home+=f'<div><span class="number">0{n}</span><div><h3>{b if ar else a}</h3><p>{d if ar else c}</p></div></div>'
